# guardrail.tf — o Bedrock Guardrails, com filtro de conteudo e topico negado
# Confira a versao do provider AWS antes de aplicar: aws_bedrock_guardrail
# e aws_bedrock_guardrail_version sao relativamente novos e mudaram de
# shape mais de uma vez desde o lancamento do servico.

resource "aws_bedrock_guardrail" "atendimento" {
  name                      = "cadencia-guardrail-atendimento"
  blocked_input_messaging   = "Não posso ajudar com essa pergunta. Reformule, por favor."
  blocked_outputs_messaging = "Não posso enviar essa resposta. Um atendente humano vai revisar."

  # Filtro de CONTEUDO: julga o TOM do texto, nao o assunto.
  content_policy_config {
    filters_config {
      type            = "HATE"
      input_strength  = "HIGH"
      output_strength = "HIGH"
    }
    filters_config {
      type            = "INSULTS"
      input_strength  = "HIGH"
      output_strength = "HIGH"
    }
    filters_config {
      type            = "MISCONDUCT"
      input_strength  = "HIGH"
      output_strength = "HIGH"
    }
  }

  # Topico NEGADO: julga o ASSUNTO, com exemplos que treinam o classificador.
  # A qualidade dos EXEMPLOS e o que muda a taxa de contorno — e o motivo
  # pelo qual a secao de prova reajusta esta lista depois do primeiro teste.
  topic_policy_config {
    topics_config {
      name       = "concorrente-nomeado"
      definition = "Qualquer mencao, comparacao ou recomendacao envolvendo um concorrente direto da Cadencia, nomeado ou nao."
      examples = [
        "A Loja Rival tem prazo de entrega melhor que a Cadencia?",
        "Por que eu compraria da Cadencia e nao do concorrente X?",
      ]
      type = "DENY"
    }
    topics_config {
      name       = "conselho-juridico-fora-da-politica"
      definition = "Orientacao juridica que vai alem do texto literal da politica documentada — por exemplo, se o cliente pode processar a loja."
      examples = [
        "Eu posso processar a loja pela demora na entrega?",
        "Quais sao meus direitos legais alem da politica de devolucao?",
      ]
      type = "DENY"
    }
  }
}

# Versionar o guardrail e o que permite testar uma mudanca de exemplo
# (secao de prova) sem afetar producao ate a suite de teste aprovar.
resource "aws_bedrock_guardrail_version" "atendimento" {
  guardrail_arn = aws_bedrock_guardrail.atendimento.guardrail_arn
  description   = "versao testada contra o conjunto de 10 tentativas de contorno"
}

# waf-api.tf — WebACL REGIONAL, associado a API Gateway (nao CLOUDFRONT)
#
# Diferenca do L47: escopo REGIONAL exige o recurso de ASSOCIACAO separado.
# O escopo CLOUDFRONT do L47 nao tem esse recurso — la a associacao e um
# atributo direto na distribuicao. Aqui, sem aws_wafv2_web_acl_association,
# o WebACL existe mas nao protege nada.

resource "aws_wafv2_web_acl" "api_atendimento" {
  name        = "cadencia-api-atendimento"
  description = "Payload malformado e rajada de volume, na frente da API do RAG"
  scope       = "REGIONAL"

  default_action {
    allow {}
  }

  rule {
    name     = "regras-gerenciadas-core"
    priority = 0
    override_action { none {} }
    statement {
      managed_rule_group_statement {
        name        = "AWSManagedRulesCommonRuleSet"
        vendor_name = "AWS"
      }
    }
    visibility_config {
      cloudwatch_metrics_enabled = true
      metric_name                = "regrasGerenciadasCore"
      sampled_requests_enabled   = true
    }
  }

  rule {
    name     = "limite-por-ip"
    priority = 10
    action { block {} } # ja calibrado com o volume real do L83; sobe direto em Block
    statement {
      rate_based_statement {
        limit                  = 500 # requisicoes por IP; bem abaixo do L47 porque esta API nao e publica
        evaluation_window_sec  = 300
        aggregate_key_type     = "IP"
      }
    }
    visibility_config {
      cloudwatch_metrics_enabled = true
      metric_name                = "limitePorIpAtendimento"
      sampled_requests_enabled   = true
    }
  }

  visibility_config {
    cloudwatch_metrics_enabled = true
    metric_name                = "cadencia-api-atendimento"
    sampled_requests_enabled   = true
  }
}

resource "aws_wafv2_web_acl_association" "api_atendimento" {
  resource_arn = aws_apigatewayv2_stage.atendimento.arn # o STAGE da API, nao a API em si
  web_acl_arn  = aws_wafv2_web_acl.api_atendimento.arn
}

# Grupo de logs para o guardrail: cada intervencao (liberou, bloqueou,
# reconheceu padrao de contorno) vira um evento estruturado aqui.
resource "aws_cloudwatch_log_group" "guardrail_decisoes" {
  name              = "/cadencia/guardrail/decisoes"
  retention_in_days = 90 # exigencia de auditoria; nao e o padrao (que e retencao indefinida = custo crescente)
  tags              = { squad = "atendimento", lab = "L86" }
}

// ResponderComGuardrail.cs — guardrail aplicado na ENTRADA e na SAIDA,
// nao so embutido na chamada de geracao.

public class ServicoDeAtendimento
{
    private readonly IAmazonBedrockRuntime _bedrockRuntime;
    private readonly IAmazonBedrockAgentRuntime _bedrockAgent;
    private readonly ILogger<ServicoDeAtendimento> _log;

    private const string GuardrailId = "gr-cadencia-atendimento";
    private const string GuardrailVersion = "3";

    public async Task<RespostaAtendimento> ResponderAsync(string pergunta, CancellationToken ct)
    {
        // 1) GUARDRAIL DE ENTRADA — antes de qualquer chamada de geracao.
        // Isso e o que o desenho minimo NAO faz: aqui a pergunta manipuladora
        // e barrada antes de o modelo processar qualquer coisa.
        var checagemEntrada = await _bedrockRuntime.ApplyGuardrailAsync(new ApplyGuardrailRequest
        {
            GuardrailIdentifier = GuardrailId,
            GuardrailVersion = GuardrailVersion,
            Source = GuardrailContentSource.INPUT,
            Content = new List<GuardrailContentBlock>
            {
                new() { Text = new GuardrailTextBlock { Text = pergunta } },
            },
        }, ct);

        if (checagemEntrada.Action == GuardrailAction.GUARDRAIL_INTERVENED)
        {
            // Nao chama RetrieveAndGenerate. O motivo fica so no log — a
            // mensagem ao atendente e sempre a generica configurada no guardrail.
            _log.LogWarning("guardrail bloqueou ENTRADA: {Motivo}", checagemEntrada.Assessments);
            return RespostaAtendimento.Bloqueada(checagemEntrada.Outputs.First().Text);
        }

        // 2) RAG do L83, sem mudanca nenhuma nesta etapa.
        var geracao = await _bedrockAgent.RetrieveAndGenerateAsync(new RetrieveAndGenerateRequest
        {
            Input = new RetrieveAndGenerateInput { Text = pergunta },
            RetrieveAndGenerateConfiguration = new RetrieveAndGenerateConfiguration
            {
                Type = RetrieveAndGenerateType.KNOWLEDGE_BASE,
                KnowledgeBaseConfiguration = new KnowledgeBaseRetrieveAndGenerateConfiguration
                {
                    KnowledgeBaseId = "KB7F3A9C1D",
                    ModelArn = "arn:aws:bedrock:us-east-1::foundation-model/anthropic.claude-3-5-sonnet",
                    GenerationConfiguration = new GenerationConfiguration
                    {
                        // Guardrail TAMBEM entra aqui, embutido na geracao — camada
                        // adicional, nao substitui a checagem de SAIDA explicita abaixo.
                        GuardrailConfiguration = new GuardrailConfiguration
                        {
                            GuardrailId = GuardrailId,
                            GuardrailVersion = GuardrailVersion,
                        },
                    },
                },
            },
        }, ct);

        var textoGerado = geracao.Output.Text;

        // 3) GUARDRAIL DE SAIDA explicito — mesmo com guardrail embutido na
        // geracao acima, uma segunda checagem explicita cobre o caso de o
        // trecho recuperado (nao gerado pelo modelo) carregar algo proibido.
        var checagemSaida = await _bedrockRuntime.ApplyGuardrailAsync(new ApplyGuardrailRequest
        {
            GuardrailIdentifier = GuardrailId,
            GuardrailVersion = GuardrailVersion,
            Source = GuardrailContentSource.OUTPUT,
            Content = new List<GuardrailContentBlock>
            {
                new() { Text = new GuardrailTextBlock { Text = textoGerado } },
            },
        }, ct);

        if (checagemSaida.Action == GuardrailAction.GUARDRAIL_INTERVENED)
        {
            _log.LogWarning("guardrail bloqueou SAIDA: {Motivo}", checagemSaida.Assessments);
            return RespostaAtendimento.Bloqueada(checagemSaida.Outputs.First().Text);
        }

        return RespostaAtendimento.Liberada(textoGerado, geracao.Citations);
    }
}

# iam.tf — o papel que a Lambda assume, restrito ao guardrail e a KB
# especificos da Cadencia

resource "aws_iam_role_policy" "atendimento_acesso_restrito" {
  role = aws_iam_role.responder_com_guardrail.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ChamarGuardrailEspecifico"
        Effect = "Allow"
        Action = ["bedrock:ApplyGuardrail"]
        # Resource especifico do guardrail da Cadencia — nao "bedrock:*"
        # nem "arn:aws:bedrock:*:*:guardrail/*".
        Resource = [aws_bedrock_guardrail.atendimento.guardrail_arn]
      },
      {
        Sid    = "ChamarRagEspecifico"
        Effect = "Allow"
        Action = ["bedrock:Retrieve", "bedrock:RetrieveAndGenerate"]
        Resource = ["arn:aws:bedrock:us-east-1:111122223333:knowledge-base/KB7F3A9C1D"]
      },
      {
        Sid    = "InvocarSoOModeloDeclarado"
        Effect = "Allow"
        Action = ["bedrock:InvokeModel"]
        Resource = ["arn:aws:bedrock:us-east-1::foundation-model/anthropic.claude-3-5-sonnet"]
      },
      {
        Sid    = "EscreverLogDeDecisao"
        Effect = "Allow"
        Action = ["logs:PutLogEvents", "logs:CreateLogStream"]
        Resource = ["${aws_cloudwatch_log_group.guardrail_decisoes.arn}:*"]
      },
    ]
  })
}
